import re

def sanitize_input(value):
    """Sanitize username input to safely handle special characters.

    Allows alphanumeric characters, hyphens, underscores, dots, and @ symbols
    to support international usernames while preventing injection attacks.
    """
    if value is None:
        return None
    # Remove any characters that are not alphanumeric, hyphen, underscore, dot, or @
    sanitized = re.sub(r'[^\w\-.@]', '', value)
    return sanitized

